do $fix$ declare d text; marker text:='   detail:=case when new_game then'; extra text:=$body$   if candidate.status<>'canceled' and not coalesce(candidate.time_tbd,false) and not coalesce(candidate.field_tbd,false) and exists(select 1 from public.locations where id=candidate.location_id and lower(name)=lower(facts->>'location')) and exists(select 1 from jsonb_array_elements(p_events) o where o->>'uid'<>uid and not (o->>'time_tbd')::boolean and not (o->>'field_tbd')::boolean and o->'facts'->>'location'=facts->>'location' and (o->>'starts_at')::timestamptz<candidate.starts_at+make_interval(mins=>candidate.duration_minutes) and (o->>'starts_at')::timestamptz+make_interval(mins=>greatest(1,least(1440,(o->>'duration')::numeric))::int)>candidate.starts_at) then
    conflict:=true;candidate.status:='suspended';candidate.venue_conflict_hold:=true;conflict_detail:=coalesce(nullif(conflict_detail,''),'another overlapping source event');
   end if;
$body$;
begin select pg_get_functiondef('public.apply_bound_calendar_feed(uuid,uuid,jsonb,text,text,text)'::regprocedure) into d; if position(marker in d)=0 then raise exception 'Unexpected function definition';end if;execute replace(d,marker,extra||marker);end $fix$;